```csharp
using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    // --- CreateOrder ---

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 10m, Quantity = 2 },
            new() { ProductName = "Gadget", Price = 25m, Quantity = 1 },
        };

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(45m, order.Total); // 10*2 + 25*1
        Assert.IsNotNull(order.Id);
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 5m, Quantity = 1 },
        };

        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("cust-1", []));
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentTime()
    {
        var before = DateTime.UtcNow;
        var items = new List<OrderItem>
        {
            new() { ProductName = "Item", Price = 1m, Quantity = 1 },
        };

        var order = _sut.CreateOrder("cust-1", items);

        Assert.IsGreaterThan(before.AddSeconds(-1), order.CreatedAt);
    }

    // --- GetOrder ---

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsOrder()
    {
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 10m, Quantity = 1 },
        };
        var created = _sut.CreateOrder("cust-1", items);

        var retrieved = _sut.GetOrder(created.Id);

        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        var result = _sut.GetOrder("does-not-exist");

        Assert.IsNull(result);
    }

    // --- GetOrdersByCustomer ---

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        var result = _sut.GetOrdersByCustomer("cust-99");

        Assert.IsEmpty(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingOrders()
    {
        var items = new List<OrderItem>
        {
            new() { ProductName = "X", Price = 5m, Quantity = 1 },
        };
        _sut.CreateOrder("cust-A", items);
        _sut.CreateOrder("cust-A", items);
        _sut.CreateOrder("cust-B", items);

        var result = _sut.GetOrdersByCustomer("cust-A");

        Assert.HasCount(2, result);
    }

    // --- Data-driven total calculation ---

    [TestMethod]
    [DataRow(10, 3, 30, DisplayName = "Single item 10×3")]
    [DataRow(0, 5, 0, DisplayName = "Zero price")]
    [DataRow(99, 1, 99, DisplayName = "Single quantity")]
    public void CreateOrder_CalculatesTotalCorrectly(int price, int qty, int expectedTotal)
    {
        var items = new List<OrderItem>
        {
            new() { ProductName = "Test", Price = price, Quantity = qty },
        };

        var order = _sut.CreateOrder("cust-1", items);

        Assert.AreEqual((decimal)expectedTotal, order.Total);
    }
}
```

**Key practices applied:**

| Practice | How |
|----------|-----|
| `sealed` test class | Prevents inheritance, improves perf |
| `Assert.ThrowsExactly<T>` | Validates exact exception type |
| `Assert.HasCount` / `Assert.IsEmpty` | Replaces `Assert.IsTrue(list.Count == N)` |
| `Assert.AreSame` | Verifies reference identity for retrieved objects |
| `[DataRow]` | Parameterized tests for total calculation |
| Constructor init | Enables `readonly` fields, clean per-test setup |
| AAA pattern | Clear Arrange/Act/Assert structure |

